const MANIFEST="{\"id\":\"/\",\"name\":\"GYM MASTERY\",\"short_name\":\"GYM MASTERY\",\"description\":\"Dein Plan. Dein Coach. Dein Fortschritt.\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"orientation\":\"portrait-primary\",\"background_color\":\"#0c0d0c\",\"theme_color\":\"#0c0d0c\",\"lang\":\"de\",\"icons\":[{\"src\":\"/icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any maskable\"},{\"src\":\"/icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any maskable\"},{\"src\":\"/icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any\"}]}\n",ICON="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\"><rect width=\"512\" height=\"512\" rx=\"112\" fill=\"#0c0d0c\"/><path d=\"M136 155h240v202H136z\" fill=\"#d4f58a\" transform=\"skewX(-7) translate(31 0)\"/><path d=\"M166 263h47l26-61 35 111 26-50h47\" fill=\"none\" stroke=\"#17200a\" stroke-width=\"20\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/></svg>\n",SW="const CACHE='gym-mastery-v2-shell';\nself.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(['/icon.svg','/manifest.webmanifest'])));self.skipWaiting()});\nself.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});\nself.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/')||url.pathname==='/mcp')return;if(['/icon.svg','/manifest.webmanifest','/gym-hero.webp'].includes(url.pathname))event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response})));if(event.request.mode==='navigate')event.respondWith(fetch(event.request).catch(()=>new Response('<html lang=\"de\"><meta name=\"viewport\" content=\"width=device-width\"><title>GYM MASTERY · Offline</title><body style=\"background:#0c0d0c;color:#f3f3e9;font-family:system-ui;padding:10vw\"><h1>Ein kurzer Verbindungsstopp.</h1><p>Dein Training bleibt gespeichert. Verbinde dich mit dem Internet, um weiterzumachen.</p><button style=\"padding:16px;background:#d4f58a;border:0;border-radius:12px\" onclick=\"location.reload()\">Erneut versuchen</button></body></html>',{headers:{'Content-Type':'text/html'}})))});\n";
const PNGS={"192":"","512":""};
